<body>
    <div class="todo-container">
        <div class="header">
            <h1>Todos</h1>
        </div>
        <div class="main">
            <div class="input-group">
                <input type="text" id="new-todo" placeholder="What needs to be done?" />
                <button id="add-btn">Add</button>
            </div>
            <div class="filters">
                <button class="filter-btn active" data-filter="all">All</button>
                <button class="filter-btn" data-filter="active">Active</button>
                <button class="filter-btn" data-filter="completed">Completed</button>
            </div>
            <ul id="todo-list"></ul>
            <div class="stats"></div>
        </div>
    </div>

    <script>
        // Initialize from localStorage or empty array
        let todos = JSON.parse(localStorage.getItem('todos')) || [];

        const todoList = document.getElementById('todo-list');
        const newTodoInput = document.getElementById('new-todo');
        const addBtn = document.getElementById('add-btn');
        const filterBtns = document.querySelectorAll('.filter-btn');
        const statsDiv = document.querySelector('.stats');

        // Render todos based on current filter
        function renderTodos(filter = 'all') {
            let filteredTodos;

            switch (filter) {
                case 'active':
                    filteredTodos = todos.filter(t => !t.completed);
                    break;
                case 'completed':
                    filteredTodos = todos.filter(t => t.completed);
                    break;
                default:
                    filteredTodos = todos;
            }

            if (filteredTodos.length === 0) {
                todoList.innerHTML = '';
                todoList.parentElement.querySelector('.empty-state') || 
                    todoList.parentElement.insertAdjacentHTML('beforeend', '<div class="empty-state">No todos yet</div>');
                return;
            }

            todoList.innerHTML = '';

            filteredTodos.forEach((todo, index) => {
                const li = document.createElement('li');
                li.className = 'todo-item' + (todo.completed ? ' completed' : '');
                li.innerHTML = `
                    <span class="todo-text">${escapeHtml(todo.text)}</span>
                    <button class="delete-btn" data-index="${index}">×</button>
                `;

                // Toggle complete on click
                li.addEventListener('click', (e) => {
                    if (e.target.className === 'delete-btn') return;
                    todo.completed = !todo.completed;
                    saveTodos();
                    renderTodos(filter);
                });

                // Delete on button click
                li.querySelector('.delete-btn').addEventListener('click', (e) => {
                    e.stopPropagation();
                    todos.splice(index, 1);
                    saveTodos();
                    renderTodos(filter);
                });

                todoList.appendChild(li);
            });

            updateStats();
        }

        // Add new todo
        function addTodo(text) {
            const trimmed = text.trim();
            if (!trimmed) return;

            todos.push({ text: trimmed, completed: false });
            newTodoInput.value = '';
            saveTodos();
            renderTodos(document.querySelector('.filter-btn.active').dataset.filter || 'all');
        }

        // Save todos to localStorage
        function saveTodos() {
            localStorage.setItem('todos', JSON.stringify(todos));
        }

        // Update stats
        function updateStats() {
            const activeCount = todos.filter(t => !t.completed).length;
            const completedCount = todos.filter(t => t.completed).length;

            if (todos.length === 0) {
                statsDiv.textContent = '';
                return;
            }

            statsDiv.textContent = `${todos.length} ${todos.length === 1 ? 'item' : 'items'} • ${activeCount} ${activeCount === 1 ? 'active' : 'active'} • ${completedCount} ${completedCount === 1 ? 'completed' : 'completed'}`;
        }

        // Escape HTML special characters
        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        // Event listeners
        addBtn.addEventListener('click', () => {
            addTodo(newTodoInput.value);
        });

        newTodoInput.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') {
                addTodo(newTodoInput.value);
            }
        });

        filterBtns.forEach(btn => {
            btn.addEventListener('click', () => {
                filterBtns.forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                renderTodos(btn.dataset.filter);
            });
        });

        // Initial render
        renderTodos();
    </script>
</body>
</html>"}
